class LRUCache
  def initialize(capacity)
    unless capacity.is_a?(Integer) && capacity >= 0
      raise ArgumentError, "capacity must be a non-negative integer"
    end

    @capacity = capacity
    @entries = {}
  end

  def get(key)
    return nil unless @entries.key?(key)

    # Reinsert the entry at the most recently used end of the hash.
    @entries[key] = @entries.delete(key)
  end

  def put(key, value)
    @entries.delete(key)
    @entries[key] = value
    @entries.shift if @entries.size > @capacity
    value
  end
end
